import {routeObjective} from './objective-routing.js?v=5.11.0';
import {grantResonance} from './resonance-link.js';
/** Portable object / discovery contract. No quest flags or recorded voices are consumed. */
export const WAYGLASS_OBJECT={id:'rook-wayglass',name:'Rook’s Wayglass',kind:'tool',portable:true,source:'Rook’s workshop',description:'A folding brass lens that follows mineral resonance. It carries no recorded voices.'};
export const RARE_MAKO=[
 {id:'anchorheart',name:'Anchorheart',core:'earth',stage:2,chapter:1,location:228,key:'workshop',place:'Rook’s workshop',prerequisite:'6:0',cost:1,growth:2,color:'#ecc78b',icon:'◆',power:1.2,costDelta:1,interrupt:true,effect:'Earth techniques gain 20% power and interrupt charged attacks; cost +1 MP.',lore:'A warm crystal growing beside an old furnace footing. Its steady pulse holds the carrier still instead of forcing another voice to repeat.'},
 {id:'mercyglass',name:'Mercyglass',core:'mend',stage:3,chapter:5,location:705,key:'secret_5',place:'the hidden archive at Ledger Quay',prerequisite:'6:1',cost:1,growth:2,color:'#a4efcf',icon:'✧',power:1.25,costDelta:-1,effect:'Mend techniques restore 25% more health and cost 1 less MP.',lore:'Pale green crystals grow where rainwater crosses the archive’s mineral seals. Mira finds no names inside them: only a pattern the crew can learn without taking anything from a person.'},
 {id:'stormseed',name:'Stormseed',core:'gale',stage:4,chapter:7,location:707,key:'secret_7',place:'the hidden garden at Ember Orchard',prerequisite:'6:2',cost:2,growth:3,color:'#b5e7ff',icon:'❋',power:1.15,costDelta:0,echo:true,effect:'Gale techniques gain 15% power and repeat once after a delay.',lore:'A blue seed of crystal forms around a living root. A first pulse leaves room for a second, like the answering bells. The orchard’s future is growth, not a voice held forever.'}
];
export const WAYGLASS_SYMBOLS=[['✦','Lantern'],['⌁','Reed'],['◉','Bell'],['❋','Leaf'],['◇','Rain'],['☾','Moon'],['✧','Star'],['≈','River'],['△','Mountain'],['♧','Root'],['⊙','Sun'],['⌘','Bridge'],['◈','Window'],['∿','Song'],['✺','Dawn']];
export const relicForStage=n=>RARE_MAKO.find(r=>r.stage===n);
export function wayglassState(s){s.kakeya??={version:2,assignments:{},solved:[]};s.kakeya.assignments??={};s.kakeya.solved??=[];s.kakeya.reveals??=[];s.kakeya.relics??=[];if((s.kakeya.version||1)<2){for(const n of s.kakeya.solved)if([2,3,4].includes(n))grantResonance(s,{sourceId:'prism:chamber:'+n,label:'Earlier prism chamber '+n,points:1});s.kakeya.version=2;}for(const id of s.kakeya.relics){const r=RARE_MAKO.find(x=>x.id===id);if(r)grantResonance(s,{sourceId:'wayglass:relic:'+id,label:r.name+' Mako recovered',points:r.growth,core:r.core});}return s.kakeya;}
export function hasWayglass(s){const bag=s.carriedObjects;return Array.isArray(bag)?bag.some(x=>(typeof x==='string'?x:x.id)===WAYGLASS_OBJECT.id):!!bag?.[WAYGLASS_OBJECT.id];}
export function journalWayglass(s,id,title,text){if(!s.story?.journal)return;if(!s.story.journal.some(x=>x.id===id))s.story.journal.push({id,title,text,chapter:s.chapter});}
export function carryWayglass(s,{legacy=false}={}){if(hasWayglass(s))return false;if(!legacy&&s.story&&!s.story.firstCore)return false;if(!s.carriedObjects)s.carriedObjects={};if(Array.isArray(s.carriedObjects))s.carriedObjects.push({...WAYGLASS_OBJECT});else s.carriedObjects[WAYGLASS_OBJECT.id]={...WAYGLASS_OBJECT};wayglassState(s).owned=true;journalWayglass(s,'wayglass:tool','Rook’s Wayglass','Rook lends the folding lens for the road. It follows mineral crystal patterns, never a captive voice. Carry it anywhere; calibrate it to reveal a seam, recover its Mako, and learn its attunement on the Resonance Paths.');return true;}
export function canCalibrate(s,n){return hasWayglass(s)&&(s.chapter>=relicForStage(n).chapter||!!s.complete)&&(n===2||wayglassState(s).solved.includes(n-1));}
export function calibrateWayglass(s,n){if(!canCalibrate(s,n))return false;const p=wayglassState(s);if(!p.solved.includes(n))p.solved.push(n);p.tracking=n;return true;}
export function ownsRelic(s,id){return (s.kakeya?.relics||[]).includes(id);}
export function seamVisible(s,r){return hasWayglass(s)&&(s.kakeya?.solved||[]).includes(r.stage)&&!ownsRelic(s,r.id)&&(s.chapter>=r.chapter||!!s.complete);}
export function collectRelic(s,id){const r=RARE_MAKO.find(x=>x.id===id);if(!r||s.scene!==r.location||!seamVisible(s,r))return false;const p=wayglassState(s);p.relics.push(id);grantResonance(s,{sourceId:'wayglass:relic:'+id,label:r.name+' Mako recovered',points:r.growth,core:r.core});if(p.tracking===r.stage)p.tracking=null;journalWayglass(s,'wayglass:'+id,'Rare Mako · '+r.name,r.lore+' '+r.effect+' The discovery adds '+r.growth+' growth points to each crew member’s Resonance Paths. Learn its attunement after the required Crystal mastery node, then equip it in Crystal craft.');return r;}
export function discoveryGrowth(s){return RARE_MAKO.reduce((v,r)=>v+(ownsRelic(s,r.id)?r.growth:0),0);}
export function isMakoAttuned(s,id,makoId){return ownsRelic(s,makoId)&&(s.skillGrid?.[id]||[]).includes('mako:'+makoId);}
export function equipRareMako(s,id,slotIndex,makoId){const r=RARE_MAKO.find(x=>x.id===makoId),h=s.heroes[id],slot=h?.loadout?.[slotIndex];if(!r||!slot||!s.recruited.includes(id)||!isMakoAttuned(s,id,makoId)||!s.cores.includes(r.core))return false;slot.core=r.core;slot.makoId=r.id;return true;}
export function installWayglassProps(world){for(const data of new Set([world.sourceData,world.data]))for(const scene of data.scenes){const isWork=scene.key==='workshop';if(scene.interior==='archive'||isWork){let o=scene.objects.find(x=>x.kakeyaStation);if(!o){o={type:'listen',kakeyaStation:true};scene.objects.push(o);}const preferred=isWork?[5,22]:[8,13],queue=[scene.arrive],seen=new Set([scene.arrive.join(',')]);for(let i=0;i<queue.length;i++)for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){const x=queue[i][0]+dx,y=queue[i][1]+dy,k=x+','+y;if(scene.floor[y]?.[x]==='.'&&!seen.has(k)){seen.add(k);queue.push([x,y]);}}const free=queue.filter(p=>!scene.objects.some(v=>v!==o&&v.xy&&Math.hypot(v.xy[0]-p[0],v.xy[1]-p[1])<1.4)&&!scene.doors.some(v=>Math.hypot(v.xy[0]-p[0],v.xy[1]-p[1])<1.4));free.sort((a,b)=>Math.hypot(a[0]-preferred[0],a[1]-preferred[1])-Math.hypot(b[0]-preferred[0],b[1]-preferred[1]));Object.assign(o,{xy:free[0]||scene.arrive,label:isWork?'Rook’s Wayglass':'Wayglass docking stand',portableObjectId:WAYGLASS_OBJECT.id,wayglassPickup:isWork});}const r=RARE_MAKO.find(x=>x.location===scene.location);if(r&&!scene.objects.some(x=>x.wayglassSeam===r.id)){const used=[...scene.objects,...scene.doors].map(x=>x.xy).filter(Boolean),hazards=scene.objects.flatMap(o=>o.type==='patrol'?(o.enemies||[]).map(e=>e[1]):o.type==='boss'?[o.xy]:[]).filter(Boolean),origin=isWork?[3,23]:[18,13],candidates=[];for(let y=2;y<scene.height-2;y++)for(let x=2;x<scene.width-2;x++)if(scene.floor[y]?.[x]==='.'&&used.every(p=>Math.hypot(p[0]-x,p[1]-y)>1.4)&&hazards.every(p=>Math.hypot(p[0]-x,p[1]-y)>3))candidates.push([x,y]);candidates.sort((a,b)=>Math.hypot(a[0]-origin[0],a[1]-origin[1])-Math.hypot(b[0]-origin[0],b[1]-origin[1]));const xy=candidates[0];if(xy)scene.objects.push({type:'cache',xy,label:r.name+' seam',wayglassSeam:r.id,portableObjectId:'mako:'+r.id});}}}
export function wayglassObjective(world){const n=world.state.kakeya?.tracking,r=relicForStage(n);if(!r||ownsRelic(world.state,r.id))return null;const seam=world.objects().find(o=>o.wayglassSeam===r.id);return routeObjective(world,{label:seam?'Wayglass: recover '+r.name:'Wayglass: seek '+r.name+' in '+r.place,scene:r.location,object:seam});}
/** Presentation derives the next action from earned state, never from a cosmetic animation. */
export function wayglassJourney(s,n,heroId=s.party?.[0]??0){const r=relicForStage(n),tuned=!!s.kakeya?.solved?.includes(n),found=ownsRelic(s,r.id),attuned=isMakoAttuned(s,heroId,r.id),equipped=attuned&&!!s.heroes[heroId]?.loadout?.some(x=>x.makoId===r.id&&x.core===r.core),near=s.scene===r.location;const at=equipped?5:attuned?4:found?3:tuned?near?2:1:0;return{at,tuned,found,attuned,equipped,heroId,steps:['Tune','Trace','Recover','Attune','Equip'].map((label,i)=>({label,state:i<at?'done':i===at?'current':'waiting'})),title:equipped?r.name+' is ready.':attuned?'Give the pattern a home.':found?'The crystal is yours.':tuned?'A clear signal.':'Listen through the lens.',instruction:equipped?'Its rare trait is active in your linked technique. Take it back to the road.':attuned?'Fit '+r.name+' to a linked socket in Crystal craft.':found?'Learn '+r.name+' attunement on the Resonance Paths.':tuned?'Recover the glowing seam in '+r.place+'.':'Choose the window that matches the glowing symbol.',action:equipped?'close':attuned?'craft':found?'grid':tuned?'follow':'tune'};}
